const body = $input.first().json.body || {};
let phone = (body.phoneNumber || '').toString().trim();
const customerName = (body.name || '').toString().trim();

// Normalize to E.164, default country UAE (+971) if no country code given
phone = phone.replace(/[^0-9+]/g, '');
if (!phone.startsWith('+')) {
  phone = phone.replace(/^0+/, ''); // strip local leading 0 (e.g. 050 123 4567)
  phone = '+971' + phone;
}

if (!/^\+\d{8,15}$/.test(phone)) {
  throw new Error('Invalid phone number: ' + phone);
}

const customer = { number: phone };
if (customerName) customer.name = customerName;

return [{
  json: {
    name: `Outbound call to ${customerName || phone}`,
    assistantId: 'c428c7f1-65bc-4207-8728-f08a214f2361',
    phoneNumberId: '6c8af7df-44de-447b-8c5e-73531fa072b6',
    customer
  }
}];

const res = $input.first().json;

// n8n HTTP node itself failed (network error / non-2xx with continueRegularOutput)
if (res && res.error) {
  const details = (res.error && (res.error.message || res.error.description)) || res.error || 'Unknown error';
  return [{
    json: {
      success: false,
      error: 'Could not initiate call',
      details: details.toString()
    }
  }];
}

const call = (res && res.data) || {};

if (call.error) {
  const details = call.error.message || (typeof call.error === 'string' ? call.error : JSON.stringify(call.error));
  return [{
    json: {
      success: false,
      error: 'Could not initiate call',
      details
    }
  }];
}

if (!call.id) {
  return [{
    json: {
      success: false,
      error: 'Could not initiate call',
      details: (res && res.message) || 'No call ID returned from AgenticFlow'
    }
  }];
}

return [{
  json: {
    success: true,
    callId: call.id,
    message: 'AMIRA is calling you now',
    estimatedRingTime: '10 seconds'
  }
}];
